const body = $('Webhook').first().json.body;
const renderRow = ($('Get Render Row').first().json || [])[0];
const profileRow = ($('Get Profile Row').first().json || [])[0];
const FREE_CORRECTIONS = 2;

// The webhook is public and takes render_id and user_id as separate inputs.
// Without this check a caller could pass their own user_id alongside someone
// else's render_id and write to a stranger's render.
const rowsExist = !!renderRow && !!profileRow;
const ownsRender = rowsExist && renderRow.user_id === body.user_id;

const isCorrection = !!body.correction_prompt;
const subscriptionActive = rowsExist && profileRow.subscription_status === 'active';
const hasCredits = rowsExist && (profileRow.credits_balance || 0) >= 1;
const freeCorrection = isCorrection && rowsExist && (renderRow.corrections_used || 0) < FREE_CORRECTIONS;

const allowed = ownsRender && (subscriptionActive || hasCredits || freeCorrection);

return [{
  json: {
    allowed,
    owns_render: ownsRender,
    rows_exist: rowsExist,
    is_correction: isCorrection,
    free_correction: freeCorrection,
    subscription_active: subscriptionActive
  }
}];

const body = $('Webhook').first().json.body;
const renderRow = $('Get Render Row').first().json[0];
const profileRow = $('Get Profile Row').first().json[0];
const access = $('Compute Access').first().json;

const isCorrection = access.is_correction;
const targetHex = isCorrection ? renderRow.color_hex : (body.color_hex || renderRow.color_hex || null);

// Which surface the user asked for, typed into the app's "Paint the" box.
const surface = (body.surface || '').trim() || 'surface';

// Up to three picks. Named explicitly so the model uses these exact colours
// and the user never has to type a colour themselves.
const colors = Array.isArray(body.colors) ? body.colors : [];
const colorList = colors.length
  ? colors.map(c => `${c.name} (${c.hex})`).join(', ')
  : (renderRow.color_name || body.color_name || '');

let basePrompt;
if (targetHex || colorList) {
  basePrompt = `Repaint the ${surface}. Use these exact colours: ${colorList || targetHex}. Keep everything else in the photo identical - same lighting, same room geometry, same hardware, same materials elsewhere.`;
} else {
  basePrompt = `Repaint the ${surface}: ${body.prompt || renderRow.prompt}. Keep everything else in the photo identical - same lighting, same room geometry, same hardware.`;
}

const correctionSuffix = isCorrection ? ` Adjustment requested: "${body.correction_prompt}".` : '';

const initImageUrl = (isCorrection && renderRow.rendered_photo_url)
  ? renderRow.rendered_photo_url
  : renderRow.original_photo_url;

return [{
  json: {
    render_id: renderRow.id,
    user_id: renderRow.user_id,
    is_correction: isCorrection,
    free_correction: access.free_correction,
    subscription_active: access.subscription_active,
    target_hex: targetHex,
    colors,
    surface,
    init_image_url: initImageUrl,
    dezgo_prompt: basePrompt + correctionSuffix,
    strength: isCorrection ? 0.3 : 0.45,
    guidance: 7,
    corrections_used: renderRow.corrections_used || 0,
    brand_logo_url: body.brand_logo_url || profileRow.brand_logo_url,
    brand_contact: body.brand_contact || profileRow.brand_contact
  }
}];

// Jimp is required at runtime: NODE_FUNCTION_ALLOW_EXTERNAL=jimp plus an
// npm install inside the container.
//
// Two things this node gets wrong if written the obvious way:
//  1. The Dezgo HTTP node REPLACES the incoming binary, so the original photo
//     is not on $input - it has to be read back off the download node.
//  2. Jimp v1 renamed most of the v0 API (getBufferAsync, MIME_JPEG, AUTO,
//     positional resize). This handles either version.
const JimpPkg = require('jimp');
const Jimp = JimpPkg.Jimp || JimpPkg;          // v1 exports { Jimp }; v0 exports the class
const JimpMime = JimpPkg.JimpMime || null;      // v1 only

function hexToRgb(hex){
  const h = String(hex).replace('#','');
  return [parseInt(h.substring(0,2),16), parseInt(h.substring(2,4),16), parseInt(h.substring(4,6),16)];
}
function rgbToLab([r,g,b]){
  const toLin = c => { c/=255; return c<=0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4); };
  const [rl,gl,bl] = [toLin(r), toLin(g), toLin(b)];
  const x = rl*0.4124 + gl*0.3576 + bl*0.1805;
  const y = rl*0.2126 + gl*0.7152 + bl*0.0722;
  const z = rl*0.0193 + gl*0.1192 + bl*0.9505;
  const xn=0.9505, yn=1.0, zn=1.089;
  const f = t => t>0.008856 ? Math.cbrt(t) : (7.787*t + 16/116);
  const fx=f(x/xn), fy=f(y/yn), fz=f(z/zn);
  return [116*fy-16, 500*(fx-fy), 200*(fy-fz)];
}
function labToRgb([L,a,b]){
  const fy=(L+16)/116, fx=fy+a/500, fz=fy-b/200;
  const fi = t => Math.pow(t,3)>0.008856 ? Math.pow(t,3) : (t-16/116)/7.787;
  const xn=0.9505, yn=1.0, zn=1.089;
  const x=fi(fx)*xn, y=fi(fy)*yn, z=fi(fz)*zn;
  const rl = x*3.2406 + y*-1.5372 + z*-0.4986;
  const gl = x*-0.9689 + y*1.8758 + z*0.0415;
  const bl = x*0.0557 + y*-0.2040 + z*1.0570;
  const toGamma = c => { c = c<=0.0031308 ? 12.92*c : 1.055*Math.pow(c,1/2.4)-0.055; return Math.min(255,Math.max(0,Math.round(c*255))); };
  return [toGamma(rl), toGamma(gl), toGamma(bl)];
}

async function readImage(bin){
  return Jimp.read(Buffer.from(bin.data, 'base64'));
}
function resizeTo(img, w, h){
  try { img.resize({ w, h }); } catch (e) { img.resize(w, h); }
  return img;
}

const build = $('Build Prompt').first().json;
const targetHex = build.target_hex;

const originalBin = $('Download Init Image').first().binary.original;
const renderedBin = $input.first().binary.data;
const original = await readImage(originalBin);
const rendered = await readImage(renderedBin);
resizeTo(rendered, original.bitmap.width, original.bitmap.height);

if (targetHex) {
  const [, ta, tb2] = rgbToLab(hexToRgb(targetHex));
  const THRESHOLD = 28; // how far a pixel must differ from the original to count as repainted
  rendered.scan(0, 0, rendered.bitmap.width, rendered.bitmap.height, function(x, y, idx){
    const or_ = original.bitmap.data[idx], og = original.bitmap.data[idx+1], ob = original.bitmap.data[idx+2];
    const rr = this.bitmap.data[idx], rg = this.bitmap.data[idx+1], rb = this.bitmap.data[idx+2];
    const dist = Math.sqrt((or_-rr)**2 + (og-rg)**2 + (ob-rb)**2);
    if (dist > THRESHOLD){
      const [L] = rgbToLab([rr,rg,rb]); // keep the model's own lighting in that pixel
      const [nr,ng,nb] = labToRgb([L, ta, tb2]);
      this.bitmap.data[idx] = nr;
      this.bitmap.data[idx+1] = ng;
      this.bitmap.data[idx+2] = nb;
    }
  });
}

if (build.brand_logo_url){
  try {
    const logo = await Jimp.read(build.brand_logo_url);
    const targetH = Math.round(rendered.bitmap.height * 0.08);
    const scale = targetH / logo.bitmap.height;
    resizeTo(logo, Math.max(1, Math.round(logo.bitmap.width * scale)), targetH);
    rendered.composite(logo, 16, rendered.bitmap.height - targetH - 16);
  } catch (e) { /* missing or broken logo url - skip rather than fail the render */ }
}

if (build.brand_contact){
  try {
    const loadFont = JimpPkg.loadFont || Jimp.loadFont;
    const fontPath = (JimpPkg.FONT_SANS_16_WHITE || (Jimp.FONT_SANS_16_WHITE));
    if (loadFont && fontPath){
      const font = await loadFont(fontPath);
      rendered.print({ font, x: 16, y: rendered.bitmap.height - 22, text: String(build.brand_contact) });
    }
  } catch (e) {
    try {
      const font = await Jimp.loadFont(Jimp.FONT_SANS_16_WHITE);
      rendered.print(font, 16, rendered.bitmap.height - 22, String(build.brand_contact));
    } catch (e2) { /* fonts unavailable in this build - logo alone is enough */ }
  }
}

const mime = JimpMime ? JimpMime.jpeg : 'image/jpeg';
const outBuffer = rendered.getBuffer
  ? await rendered.getBuffer(mime)
  : await rendered.getBufferAsync(mime);

return [{
  json: { render_id: build.render_id },
  binary: { data: { data: outBuffer.toString('base64'), mimeType: 'image/jpeg', fileName: 'render.jpg' } }
}];
